#!/bin/sh
# prerm for the trisse-home .deb (as generated by dh_installsystemd): stop the
# service when the package is removed. Upgrades restart it in postinst.
set -e

if [ -d /run/systemd/system ] && [ "$1" = remove ]; then
	deb-systemd-invoke stop trisse-home-setup-info.timer trisse-home.service >/dev/null || true
fi

exit 0
